import Foundation

public final class ContentStore: @unchecked Sendable {
    public static let shared = ContentStore()
    public let concepts: [Concept]
    public let phrases: [Phrase]
    public init() { concepts = ContentFactory.concepts; phrases = ContentFactory.phrases }
    public func concepts(for topic: Topic) -> [Concept] { concepts.filter { $0.topic == topic } }
    public func search(_ query: String, language: Language) -> [Concept] { guard !query.isEmpty else { return concepts }; return concepts.filter { $0.spanish.localizedCaseInsensitiveContains(query) || $0.realizations[language]!.text.localizedCaseInsensitiveContains(query) } }
}

